TransactionCountByMonth = {
	init: async function (app, container) { 
		var query = "B2B/Invoice/StatsByCalendarMonth(SystemId='" + app.Config.B2B.TransactionSource + "')";
		await api.get(query).then( function(data) {
			data.value.reverse();
			TransactionCountByMonth.initTransactionValuesChart(container, data.value);
		});
	},

	initChart: function(args, element) {
		var chart = new Chart(element, args);
		chart.init();
		return chart;
	},

	initTransactionValuesChart: function(container, data) {
		console.log({ component: "TransactionCountByMonth", data: data });
		
		var args = {
				showLegend: true,
				series: [{ name: "[resource_displayname[Count]]", data: new Array() }],
				categories: data.filter(i => i.Currency == "EUR").map(i => i.CalendarMonth),
				max: data.map(i => i.Count).sort(function(a,b){return b - a})[0],
				type: "column"
			};

		for(var i = 0; i < args.categories.length; i++) {
			var month = args.categories[i];
			var value = data
				.filter(i => i.CalendarMonth === month)
				.map(i => i.Count)
				.reduce(function(a, b){ return a + b; });
			args.series[0].data.push(value);
		};
		return TransactionCountByMonth.initChart(args, $("[name=transactionCount]", container));
	}
};
